#!/bin/bash
#
# Run this script from a directory containing a package.json to fetch as many
# of its dependencies as possible from LOCKED_NODE_MODULES
#
# Copyright (c) 2015 Silk Laboratories, Inc.
# All Rights Reserved.
# Confidential and Proprietary - Silk Laboratories, Inc.

source $(dirname $0)/../gonk/gnutools.sh
SILK_SDK_GLUE=$(readlink -f $(dirname $0)/../sdk/glue)

LOCKED_NODE_MODULES=$(readlink -f $(dirname $0)/node_modules)

LIST_REMOTE_DEPS=$(dirname $0)/list_remote_deps.js

mkdir -p node_modules/
if [[ ! -f node_modules/.ok ]]; then
  for mod_ver in $($LIST_REMOTE_DEPS -v package.json | sort -u); do
    mod=${mod_ver%%@*}
    if [[ $mod = silk-sdk-glue ]]; then
      # TODO: Remove this block once the SDK is published
      rsync -a $SILK_SDK_GLUE/{*,.*} node_modules/$mod
      continue
    fi

    locked_module="$($(dirname $0)/locate.sh $mod_ver || true)"
    if [[ -n $locked_module ]]; then
      ln -sf $locked_module/$mod node_modules/$mod
      rsync -qa $locked_module/$mod node_modules
      if [[ -d $locked_module/.bin ]]; then
        rsync -qa $locked_module/.bin node_modules/
      fi
    fi
  done
  touch node_modules/.ok
fi
